using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.FNZ.Transacciones;namespace GraphApi.Services.FNZ.Transacciones{    public class TransaccionesService : ITransaccionesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TransaccionesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTransacciones>> GetTransacciones(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM fnz.vsTransacciones (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTransacciones>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTransaccionesDynamic(            int? transaccionID,            int? cuentaID,            string? cuenta,            string? tipoCuenta,            int? usuarioID,            string? nombreUsuario,            int? tipoMovimientoID,            string? tipoMovimiento,            decimal? cargo,            decimal? abono,            string? motivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TransaccionID, CuentaID, Cuenta, TipoCuenta, UsuarioID, NombreUsuario, TipoMovimientoID, TipoMovimiento, Cargo, Abono, Motivo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM fnz.vsTransacciones (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (transaccionID.HasValue)            {                vSql.Append(" AND TransaccionID = @TransaccionID");                vParameters.Add("TransaccionID",transaccionID);            }            if (!string.IsNullOrWhiteSpace(cuenta))            {                vSql.Append(" AND Cuenta LIKE @Cuenta");                vParameters.Add("Cuenta",$"%{cuenta}%");            }            if (!string.IsNullOrWhiteSpace(tipoCuenta))            {                vSql.Append(" AND TipoCuenta LIKE @TipoCuenta");                vParameters.Add("TipoCuenta",$"%{tipoCuenta}%");            }            if (!string.IsNullOrWhiteSpace(nombreUsuario))            {                vSql.Append(" AND NombreUsuario LIKE @NombreUsuario");                vParameters.Add("NombreUsuario",$"%{nombreUsuario}%");            }            if (!string.IsNullOrWhiteSpace(tipoMovimiento))            {                vSql.Append(" AND TipoMovimiento LIKE @TipoMovimiento");                vParameters.Add("TipoMovimiento",$"%{tipoMovimiento}%");            }            if (!string.IsNullOrWhiteSpace(motivo))            {                vSql.Append(" AND Motivo LIKE @Motivo");                vParameters.Add("Motivo",$"%{motivo}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTransacciones> CreateTransacciones(clCreateTransacciones objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO fnz.Transacciones                (CuentaID, UsuarioID, TipoMovimientoID, Cargo, Abono, Motivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@CuentaID, @UsuarioID, @TipoMovimientoID, @Cargo, @Abono, @Motivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.CuentaID,                objInput.UsuarioID,                objInput.TipoMovimientoID,                objInput.Cargo,                objInput.Abono,                objInput.Motivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TransaccionID, CuentaID, Cuenta, TipoCuenta, UsuarioID, NombreUsuario, TipoMovimientoID, TipoMovimiento, Cargo, Abono, Motivo, bEliminado                FROM fnz.vsTransacciones (NOLOCK)                WHERE TransaccionID = @TransaccionID;";            var vReadParams = new { TransaccionID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTransacciones>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Transaccione con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTransacciones?> UpdateTransacciones(clUpdateTransacciones objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TransaccionID", objInput.TransaccionID);            if (objInput.CuentaID != null)            {                vSets.Add("CuentaID = @CuentaID");                vParameters.Add("CuentaID", objInput.CuentaID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.TipoMovimientoID != null)            {                vSets.Add("TipoMovimientoID = @TipoMovimientoID");                vParameters.Add("TipoMovimientoID", objInput.TipoMovimientoID);            }            if (objInput.Cargo != null)            {                vSets.Add("Cargo = @Cargo");                vParameters.Add("Cargo", objInput.Cargo);            }            if (objInput.Abono != null)            {                vSets.Add("Abono = @Abono");                vParameters.Add("Abono", objInput.Abono);            }            if (objInput.Motivo is not null)            {                vSets.Add("Motivo = @Motivo");                vParameters.Add("Motivo", objInput.Motivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE fnz.Transacciones                SET {vSetClause}                WHERE TransaccionID = @TransaccionID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TransaccionID, CuentaID, Cuenta, TipoCuenta, UsuarioID, NombreUsuario, TipoMovimientoID, TipoMovimiento, Cargo, Abono, Motivo, bEliminado                FROM fnz.vsTransacciones (NOLOCK)                WHERE TransaccionID = @TransaccionID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTransacciones>(sSelect, new {  objInput.TransaccionID });        }        public async Task<bool> DeleteTransacciones(int nTransaccionesID)        {            const string sSql = @"                DELETE FROM fnz.Transacciones                WHERE TransaccionID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTransaccionesID });            return vAffected > 0;        }    }}